package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"
)

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	ans := 0
	met := false

	for scanner.Scan() {
		input := scanner.Text()
		if input == "BBBBBBBB" {
			ans++
		} else if !met {
			count := strings.Count(input, "B")
			ans += count
			met = true
		}
	}

	fmt.Println(ans)
}

